insert into public.decisions
  (number, statement, reason, status, decided_by_name, decided_at, origin, origin_ref)
overriding system value
values
  (198, 'Answers G8 to G11. G8: listening keeps a message''s text, its sender, when it was sent and the ids of its link, never Slack''s payload, and deletes it 30 days after it was sent; a decision proposed from it keeps its link. G9: the bot posts a note in the channel when listening starts or stops, and the web app has one page saying what is read and kept and how to switch it off or have something deleted. G10: capture uses the smallest current model, Claude Haiku 5.5, once per thread gone quiet, measured against the budget in the first days before more channels are switched on. G11: a decision proposed from listening is confirmed by anyone who wrote in the thread it came from, until areas have owners (3.1)', 'Chosen in conversation, all as recommended', 'active', 'the owner', '2026-11-25T00:00:00Z', 'import', '198'),
  (199, 'How slice 2.5 is built (`slice-2-5.md`). A channel is listened to after "@hippidy listen" and no longer after "@hippidy stop listening", each the whole message, from anyone; the bot posts a note in the channel and records who and when. The `message` events of public and private channels reach the API, which drops those of channels not listened to before writing anything and keeps the rest as text, following edits and deletions. On reconcile, at most three threads quiet for 30 minutes and with new messages are each read once by `claude-haiku-5-5` with structured output, outside any sync lease; a thread the bot was mentioned in is skipped, since the teammate records there. What it finds is written only as proposals (origin `capture`), with the ids of the thread''s writers, who may confirm them in 2.6; nothing is posted in the thread. Every call''s tokens and cost are recorded, and capture stops for the UTC day at $1 (`CAPTURE_DAILY_BUDGET_CENTS`). Reconcile deletes messages 30 days after they were sent', 'Keeps 176''s limits (no reply to an unmentioned message, no model per message, only proposals) with one cheap call per quiet thread. A command whose whole text must match cannot be set off by a question that mentions listening. Skipping mentioned threads avoids recording the same decision twice. A daily stop bounds a mistake in the quiet-thread query to a dollar', 'active', 'the owner', '2026-11-25T00:00:00Z', 'import', '199')
on conflict (origin, origin_ref) where origin_ref is not null do nothing;
